<script setup>
import {reactive} from 'vue'
import {Button,TextInput,Select} from '@itpmining/vue-basic-components'
import {useI18n} from 'vue-i18n'
const props=defineProps({organizations:Array,companyId:Number,busy:Boolean});const emit=defineEmits(['save']);const {t}=useI18n()
const value=reactive({company_id:props.companyId||'',period_from:'',period_to:'',due_date:'',basis:'',items:[{description:'',quantity:1,unit_minor:0,price:'0.00'}]})
function save(){const items=[];for(const i of value.items){const m=/^(\d{1,10})(?:[.,](\d{1,2}))?$/.exec(i.price);if(!m)return;items.push({description:i.description,quantity:Number(i.quantity),unit_minor:Number(m[1])*100+Number((m[2]||'').padEnd(2,'0'))})}emit('save',{...value,items})}
</script>
<template><form class="editor" @submit.prevent="save"><p class="muted">{{t('adminPortal.invoiceDraftNotice')}}</p><label>{{t('adminPortal.organization')}}<Select v-model="value.company_id" :options="organizations" value-key="id" display-key="name" /></label><div class="form-grid"><label v-for="key in ['period_from','period_to','due_date']" :key="key">{{t('adminPortal.'+key)}}<TextInput v-model="value[key]" type="date" required /></label></div><label>{{t('adminPortal.basis')}}<TextInput v-model="value.basis" required /></label><fieldset v-for="(item,i) in value.items" :key="i"><legend>{{i+1}}</legend><label>{{t('adminPortal.description')}}<TextInput v-model="item.description" required /></label><div class="form-grid"><label>{{t('adminPortal.quantity')}}<TextInput v-model="item.quantity" type="number" min="1" required /></label><label>{{t('adminPortal.priceMinor')}}<TextInput v-model="item.price" type="text" inputmode="decimal" required /></label></div><Button v-if="value.items.length>1" color="secondary" :text="t('adminPortal.remove')" @click="value.items.splice(i,1)" /></fieldset><div class="actions"><Button color="secondary" :text="t('adminPortal.addItem')" @click="value.items.push({description:'',quantity:1,unit_minor:0,price:'0.00'})" /><Button type="submit" :text="t('adminPortal.saveDraft')" :disabled="busy" /></div></form></template>
